app.Use(async (context, next) =>
{
    if (!IngressRules.TryValidate(context.Request, out var error))
    {
        context.Response.StatusCode = StatusCodes.Status400BadRequest;
        await context.Response.WriteAsJsonAsync(new { error });
        return;                        // short-circuit: handler never runs
    }
    await next(context);
});

app.MapPut("/todos/{id}", UpdateTodo)
   .AddEndpointFilter(async (ctx, next) =>
   {
       var todo = ctx.GetArgument<Todo>(0);
       var error = TodoValidator.Validate(todo);
       if (error is not null) return Results.Problem(error);   // handler not called
       return await next(ctx);
   });

